steps_json:
[
    {
        "title": "画出坐标系和直线",
        "description": "先观察一次函数 $y=-2x+8$。它的图象是一条直线，通常先找与两坐标轴的交点，再处理面积和范围问题。",
        "bubbleText": "这类题最省力的办法，就是先找“撞到坐标轴”的两个点。两点一连，图形和数量关系都清楚了。",
        "bubblePos": {
            "x": 500,
            "y": 210
        }
    },
    {
        "title": "求与 y 轴交点",
        "description": "令 $x=0$，得 $y=-2\\times 0+8=8$，所以图象与 $y$ 轴交于点 $(0,8)$。",
        "bubbleText": "在 $y$ 轴上，横坐标一定是 $0$。把 $x=0$ 代进去，就立刻得到纵截距是 $8$。",
        "bubblePos": {
            "x": 310,
            "y": 130
        }
    },
    {
        "title": "求与 x 轴交点",
        "description": "令 $y=0$，得 $0=-2x+8$，所以 $2x=8$，解得 $x=4$，因此图象与 $x$ 轴交于点 $(4,0)$。",
        "bubbleText": "在 $x$ 轴上，纵坐标一定是 $0$。所以把 $y$ 设成 $0$，就能算出横截距是 $4$。",
        "bubblePos": {
            "x": 620,
            "y": 430
        }
    },
    {
        "title": "确定三角形",
        "description": "函数图象与 $x$ 轴、$y$ 轴围成一个直角三角形，三个顶点分别是 $(0,0)$、$(0,8)$、$(4,0)$。",
        "bubbleText": "两条坐标轴本来就互相垂直，所以围成的是直角三角形，求面积会很方便。",
        "bubblePos": {
            "x": 340,
            "y": 360
        }
    },
    {
        "title": "找底和高",
        "description": "这个直角三角形的一条直角边在 $x$ 轴上，长度为 $4$；另一条直角边在 $y$ 轴上，长度为 $8$。",
        "bubbleText": "底就是从原点到 $(4,0)$，长 $4$；高就是从原点到 $(0,8)$，长 $8$。",
        "bubblePos": {
            "x": 190,
            "y": 290
        }
    },
    {
        "title": "计算面积",
        "description": "三角形面积为 $\\frac{1}{2}\\times 4\\times 8=16$。",
        "bubbleText": "直角三角形面积公式就是“底乘高再除以 2”，所以面积一下就出来了：$16$。",
        "bubblePos": {
            "x": 585,
            "y": 150
        }
    },
    {
        "title": "分析 y 大于 0 的位置",
        "description": "当 $y>0$ 时，表示函数图象在 $x$ 轴的上方。观察图象可知，直线在与 $x$ 轴交点左边的一段位于 $x$ 轴上方。",
        "bubbleText": "$y$ 是正数，意思就是点在 $x$ 轴上面。我们只要看直线哪一段在上面就行。",
        "bubblePos": {
            "x": 430,
            "y": 300
        }
    },
    {
        "title": "写出 x 的范围",
        "description": "因为图象与 $x$ 轴交于 $x=4$，且题目讨论的是由两轴围成的这段图形区域内的横坐标，所以当 $y>0$ 时，$x$ 的取值范围是 $0<x<4$。",
        "bubbleText": "从原点往右看，直到碰到 $x$ 轴交点 $4$ 之前，直线都在上方，所以这里的 $x$ 是 $0$ 到 $4$ 之间，但不能取两头。",
        "bubblePos": {
            "x": 350,
            "y": 425
        }
    },
    {
        "title": "整理两个答案",
        "description": "所以本题结论为：\n（1）函数图象与 $x$ 轴、$y$ 轴围成的三角形面积是 $16$；\n（2）当 $y>0$ 时，$x$ 的取值范围是 $0<x<4$。",
        "bubbleText": "一个是面积，一个是范围。前面找出的两个截距，正好把这两个问题都解决了。",
        "bubblePos": {
            "x": 585,
            "y": 395
        }
    },
    {
        "title": "代值验证",
        "description": "检验：当 $x=2$ 时，$y=-2\\times 2+8=4>0$，满足 $0<x<4$；当 $x=5$ 时，$y=-2\\times 5+8=-2<0$，不满足条件，说明答案正确。",
        "bubbleText": "随便代一个区间里的数和区间外的数试一试：里面确实让 $y$ 变正，外面就不行，说明范围判断是对的。",
        "bubblePos": {
            "x": 390,
            "y": 515
        }
    }
]
